<?php
namespace App\Http\Middleware; use Closure; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\Response;
final class ApiCors { public function handle(Request $r,Closure $next):Response{$origin=$r->header('Origin');$allowed=array_filter(array_map('trim',explode(',',(string)env('FRONTEND_ORIGINS','http://localhost:5173'))));$response=$r->isMethod('OPTIONS')?response('',204):$next($r);if($origin&&in_array($origin,$allowed,true)){$response->headers->set('Access-Control-Allow-Origin',$origin);$response->headers->set('Vary','Origin');$response->headers->set('Access-Control-Allow-Credentials','true');$response->headers->set('Access-Control-Allow-Headers','Content-Type, X-Request-ID');$response->headers->set('Access-Control-Allow-Methods','GET, POST, PATCH, DELETE, OPTIONS');}return $response;} }
